"""Generated byte fixtures only; no authentic movie, mask or MAT/HDF5 decode."""
import copy
import hashlib
import json
import os
from pathlib import Path
import shutil
import sys
import tempfile
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from suns2_benchmark import fold_inputs as f
from suns2_benchmark.constants import VIDEO_IDS, TASK_SLUG


class FoldProjectionTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(
            prefix="generated-", dir=os.environ.get("TMPDIR") or None)
        self.root = Path(self.temp.name).resolve()
        self.bank = self.root / "bank"
        self.bank.mkdir()
        self.code = self.root / "code"
        self.code.mkdir()
        self.private = self.root / "private"
        self.private.mkdir()
        self.dest = self.root / "candidate-fold"
        self.material_path = self.private / "material.json"
        self.code_path = self.private / "code.json"
        self.lock = self.private / "frozen.json"
        self.procedure = "1" * 64
        self.material = {
            "schema": f.MATERIAL_SCHEMA, "task": TASK_SLUG,
            "source": {"object_id": 49636131, "version": 3, "archive_bytes": 248562067,
                       "archive_sha256": "2" * 64,
                       "archive_md5": "e4aaf274478253cfea21580594ab2e36"},
            "authentication_receipt_sha256": "3" * 64,
            "status": "authenticated_original_inputs", "videos": [], "manual_masks": [],
            "common_support": {"temporal_template": "quarantined_pending_provenance"},
        }
        for key, role in (("videos", "video"), ("manual_masks", "manual_mask")):
            for video in VIDEO_IDS:
                name = video + ".h5" if role == "video" else "GT Masks/FinalMasks_" + video + ".mat"
                content = ("GENERATED BYTE FIXTURE, NOT HDF5/MAT: " + role + "/" + video).encode()
                path = self.bank / name
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_bytes(content)
                self.material[key].append({
                    "video_id": video, "role": role, "path": name, "source_member": name,
                    "bytes": len(content), "sha256": hashlib.sha256(content).hexdigest(),
                    "shape": [6000, 50, 50] if role == "video" else [50, 50, f.GROUND_TRUTH_COUNTS[video]],
                })
        (self.code / "method.py").write_bytes(b"# Generated official-code interface fixture\n")
        self.code_manifest = {
            "schema": f.CODE_SCHEMA, "task": TASK_SLUG, "release": "v1.2.0",
            "commit": f.CODE_RELEASES["v1.2.0"],
            "source_role": "reviewed_official_code_without_answers_or_weights",
            "files": [{"path": "method.py", "bytes": (self.code / "method.py").stat().st_size,
                       "sha256": hashlib.sha256((self.code / "method.py").read_bytes()).hexdigest()}],
        }
        self.addCleanup(self.cleanup)

    def cleanup(self):
        for path, directories, _ in os.walk(self.root):
            os.chmod(path, 0o700)
            for directory in directories:
                p = Path(path) / directory
                if not p.is_symlink():
                    os.chmod(p, 0o700)
        self.temp.cleanup()

    def pin(self, path, value):
        data = json.dumps(value, sort_keys=True).encode()
        path.write_bytes(data)
        return hashlib.sha256(data).hexdigest()

    def prepare(self, condition="paper_data"):
        self.material_sha = self.pin(self.material_path, self.material)
        self.code_sha = self.pin(self.code_path, self.code_manifest) if condition.endswith("official_code") else None
        f.freeze_procedure(self.lock, self.procedure, condition, self.material_sha, self.code_sha)
        return condition

    def project(self, fold=0, condition="paper_data", destination=None):
        args = {}
        if condition.endswith("official_code"):
            args = {"code_manifest_path": self.code_path, "trusted_code_sha256": self.code_sha,
                    "code_root": self.code}
        return f.project_fold(self.material_path, self.material_sha, self.bank,
                              destination or self.dest, fold, condition, self.procedure, self.lock, **args)

    def test_complete_same_nine_movies_and_only_eight_training_labels(self):
        self.prepare()
        panel = self.project(0)
        self.assertEqual(len(panel["files"]), 17)
        videos = [x["video_id"] for x in panel["files"] if x["role"] == "video"]
        masks = [x["video_id"] for x in panel["files"] if x["role"] == "manual_mask"]
        self.assertEqual(videos, list(VIDEO_IDS))
        self.assertEqual(masks, list(VIDEO_IDS[1:]))
        text = (self.dest / "fold.json").read_text()
        self.assertNotIn(self.material["manual_masks"][0]["sha256"], text)
        self.assertNotIn(self.material_sha, text)
        self.assertNotIn(str(self.bank), text)
        self.assertNotIn(self.material["authentication_receipt_sha256"], text)

    def test_spec_only_no_payload_copy_and_exact_read_accounting(self):
        self.prepare()
        self.project()
        self.assertEqual([p.name for p in self.dest.iterdir()], ["fold.json"])
        receipt = json.loads(Path(str(self.lock) + ".fold-0.claim.json.complete.json").read_text())
        self.assertEqual(receipt["payload_bytes_copied"], 0)
        self.assertEqual(receipt["material_bytes_hashed"], sum(x["bytes"] for k in ("videos", "manual_masks") for x in self.material[k]))
        self.assertEqual(len(receipt["bindings"]), 17)
        self.assertTrue(all(row["read_only"] for row in receipt["bindings"]))
        self.assertTrue(all("FinalMasks_" + VIDEO_IDS[0] not in row["source_path"] for row in receipt["bindings"]))

    def test_asymmetric_generated_bytes_preserved_and_coordinate_contract_declared(self):
        # Deliberately asymmetric byte matrices, not scientific HDF5/MAT files.
        # Coordinate conversion itself is tested by the parent's coordinates.py.
        movie = bytes([10, 11, 12, 20, 21, 22])  # 2 rows x 3 columns.
        mask = bytes([0, 0, 1, 0, 0, 1])  # 3 columns x 2 rows, deliberately asymmetric.
        for entry, content in ((self.material["videos"][0], movie),
                               (self.material["manual_masks"][1], mask)):
            (self.bank / entry["path"]).write_bytes(content)
            entry["bytes"] = len(content)
            entry["sha256"] = hashlib.sha256(content).hexdigest()
        self.prepare()
        panel = self.project()
        self.assertEqual(panel["coordinates"]["movie_axes"], ["time", "row", "col"])
        self.assertEqual(panel["coordinates"]["mask_axes"], ["col", "row", "neuron"])
        self.assertEqual(panel["coordinates"]["relation"], "movie[t,row,col] corresponds to Masks[col,row,neuron]")
        self.assertEqual((self.bank / self.material["videos"][0]["path"]).read_bytes(), movie)
        self.assertEqual((self.bank / self.material["manual_masks"][1]["path"]).read_bytes(), mask)
        receipt = json.loads(Path(str(self.lock) + ".fold-0.claim.json.complete.json").read_text())
        pins = {row["source_path"]: row["sha256"] for row in receipt["bindings"]}
        self.assertEqual(pins[self.material["videos"][0]["path"]], hashlib.sha256(movie).hexdigest())
        self.assertEqual(pins[self.material["manual_masks"][1]["path"]], hashlib.sha256(mask).hexdigest())

    def test_all_nine_fold_specs_use_original_order(self):
        self.prepare()
        for index, video in enumerate(VIDEO_IDS):
            panel = self.project(index, destination=self.root / ("fold-" + str(index)))
            self.assertEqual(panel["held_video"], video)
            self.assertEqual(len(panel["files"]), 17)
            self.assertNotIn(video, [r["video_id"] for r in panel["files"] if r["role"] == "manual_mask"])

    def test_untrusted_changed_manifest_refused_even_if_self_declared_authenticated(self):
        self.prepare()
        self.material["authentication_receipt_sha256"] = "4" * 64
        self.pin(self.material_path, self.material)
        with self.assertRaises(f.ProjectionError):
            self.project()
        self.assertFalse(self.dest.exists())

    def test_incomplete_and_unauthenticated_original_support_refused(self):
        self.material["videos"].pop()
        with self.assertRaises(f.ProjectionError):
            f.validate_material_manifest(self.material)
        self.material["status"] = "metadata_only"
        with self.assertRaises(f.ProjectionError):
            f.validate_material_manifest(self.material)

    def test_source_object_shape_and_member_identity_checked(self):
        for field, value in (("object_id", 49636137), ("archive_bytes", 399690268), ("version", 2)):
            value_copy = copy.deepcopy(self.material)
            value_copy["source"][field] = value
            with self.assertRaises(f.ProjectionError):
                f.validate_material_manifest(value_copy)
        wrong = copy.deepcopy(self.material)
        wrong["videos"][0]["shape"] = [50, 50, 6000]
        with self.assertRaises(f.ProjectionError):
            f.validate_material_manifest(wrong)
        wrong["videos"][0]["source_member"] = "different.h5"
        with self.assertRaises(f.ProjectionError):
            f.validate_material_manifest(wrong)

    def test_changed_payload_checksum_refused_before_destination(self):
        self.prepare()
        path = self.bank / self.material["videos"][0]["path"]
        data = path.read_bytes()
        path.write_bytes(b"X" + data[1:])
        with self.assertRaises(f.ProjectionError):
            self.project()
        self.assertFalse(self.dest.exists())

    def test_held_mask_is_validated_but_never_projected(self):
        self.prepare()
        path = self.bank / self.material["manual_masks"][0]["path"]
        path.write_bytes(b"bad")
        with self.assertRaises(f.ProjectionError):
            self.project()
        self.assertFalse(self.dest.exists())

    def test_final_file_symlink_refused(self):
        row = self.material["videos"][0]
        path = self.bank / row["path"]
        other = self.root / "outside"
        path.rename(other)
        path.symlink_to(other)
        self.prepare()
        with self.assertRaises(f.ProjectionError):
            self.project()

    def test_parent_directory_symlink_refused(self):
        actual = self.bank / "GT Masks"
        other = self.root / "masks-outside"
        actual.rename(other)
        actual.symlink_to(other, target_is_directory=True)
        self.prepare()
        with self.assertRaises(f.ProjectionError):
            self.project()

    def test_hardlinked_source_is_refused(self):
        row = self.material["videos"][0]
        os.link(self.bank / row["path"], self.root / "alias")
        self.prepare()
        with self.assertRaises(f.ProjectionError):
            self.project()

    def test_fifo_source_refused_without_waiting_for_writer(self):
        path = self.bank / self.material["videos"][0]["path"]
        path.unlink()
        os.mkfifo(path)
        self.prepare()
        with self.assertRaises(f.ProjectionError):
            self.project()
        self.assertFalse(self.dest.exists())

    def test_traversal_case_collision_and_role_aliases_refused(self):
        for mutation in ("traversal", "collision", "hash_alias"):
            wrong = copy.deepcopy(self.material)
            if mutation == "traversal":
                wrong["videos"][0]["path"] = "../escape.h5"
            elif mutation == "collision":
                wrong["manual_masks"][0]["path"] = wrong["videos"][0]["path"].upper()
            else:
                wrong["videos"][0]["sha256"] = wrong["manual_masks"][0]["sha256"]
            with self.assertRaises(f.ProjectionError):
                f.validate_material_manifest(wrong)

    def test_procedure_and_condition_are_immutable(self):
        self.prepare()
        self.procedure = "5" * 64
        with self.assertRaises(f.ProjectionError):
            self.project()
        with self.assertRaises(f.ProjectionError):
            f.freeze_procedure(self.lock, self.procedure, "paper_data", self.material_sha)

    def test_duplicate_fold_attempt_refused_at_different_destination(self):
        self.prepare()
        self.project()
        second = self.root / "second"
        with self.assertRaises(f.ProjectionError):
            self.project(destination=second)
        self.assertFalse(second.exists())

    def test_existing_or_overlapping_destination_refused(self):
        self.prepare()
        self.dest.mkdir()
        with self.assertRaises(f.ProjectionError):
            self.project()
        with self.assertRaises(f.ProjectionError):
            self.project(destination=self.bank / "candidate-fold")

    def test_code_condition_has_same_data_and_declared_pinned_release(self):
        condition = self.prepare("paper_data_official_code")
        panel = self.project(condition=condition)
        self.assertEqual(len(panel["files"]), 17)
        self.assertEqual(panel["code_identity"], {"release": "v1.2.0", "commit": f.CODE_RELEASES["v1.2.0"]})
        self.assertEqual([x["path"] for x in panel["code_files"]], ["official_code/method.py"])
        self.assertEqual(len(list(self.dest.iterdir())), 1)

    def test_code_release_mismatch_and_weights_rejected(self):
        self.code_manifest["commit"] = "0" * 40
        with self.assertRaises(f.ProjectionError):
            f.validate_code_manifest(self.code_manifest)
        self.code_manifest["commit"] = f.CODE_RELEASES["v1.2.0"]
        self.code_manifest["files"][0]["path"] = "Weights/model.h5"
        with self.assertRaises(f.ProjectionError):
            f.validate_code_manifest(self.code_manifest)

    def test_empty_source_code_is_allowed_but_data_is_not_empty(self):
        self.code_manifest["files"][0]["bytes"] = 0
        self.code_manifest["files"][0]["sha256"] = hashlib.sha256(b"").hexdigest()
        f.validate_code_manifest(self.code_manifest)
        self.material["videos"][0]["bytes"] = 0
        with self.assertRaises(f.ProjectionError):
            f.validate_material_manifest(self.material)

    def test_only_exact_official_extensionless_license_paths_are_allowed(self):
        for path in ("LICENSE", "SUNS2/LICENSE"):
            with self.subTest(accepted=path):
                manifest = copy.deepcopy(self.code_manifest)
                manifest["files"][0]["path"] = path
                f.validate_code_manifest(manifest)
        for path in ("NOTICE", "COPYING", "ANE/LICENSE", "SUNS2/NOTICE",
                     "license", "SUNS2/license", "SUNS2/../LICENSE",
                     "Weights/LICENSE", "results/LICENSE", "data/LICENSE",
                     "weights/license.txt", "method.h5", "GT Masks/hidden.py"):
            with self.subTest(refused=path):
                manifest = copy.deepcopy(self.code_manifest)
                manifest["files"][0]["path"] = path
                with self.assertRaises(f.ProjectionError):
                    f.validate_code_manifest(manifest)

    def test_code_in_paper_only_condition_and_template_override_refused(self):
        self.prepare()
        with self.assertRaises(f.ProjectionError):
            f.project_fold(self.material_path, self.material_sha, self.bank, self.dest, 0,
                           "paper_data", self.procedure, self.lock, code_root=self.code)
        self.material["common_support"]["temporal_template"] = "available"
        with self.assertRaises(f.ProjectionError):
            f.validate_material_manifest(self.material)

    def test_duplicate_manifest_json_keys_refused(self):
        data = b'{"schema":"one","schema":"two"}'
        self.material_path.write_bytes(data)
        with self.assertRaises(f.ProjectionError):
            f._read_pinned_manifest(self.material_path, hashlib.sha256(data).hexdigest())

    def test_late_failure_retains_claim_and_failure_receipt(self):
        self.prepare()
        original = f._exclusive_json
        def fail_participant(path, value, mode=0o400):
            if Path(path).name == "fold.json":
                raise OSError("generated write failure")
            return original(path, value, mode)
        f._exclusive_json = fail_participant
        try:
            with self.assertRaises(OSError):
                self.project()
        finally:
            f._exclusive_json = original
        claim = Path(str(self.lock) + ".fold-0.claim.json")
        self.assertTrue(claim.exists())
        self.assertTrue(Path(str(claim) + ".failed.json").exists())
        self.assertFalse(Path(str(claim) + ".complete.json").exists())


if __name__ == "__main__":
    unittest.main(verbosity=2)
